import expr
malos = ['1 + * 2', '(1+2', '2 +', 'foo(', '1 @ 2', 'x + 1', 'sqrt(1, 2)', 'sqrt()',
         '', '   ', ')', '1 2', '1/0', '3 % 0', 'noexiste(1)', '1..2', 'a b c']
for fuente in malos:
    try:
        expr.evaluar(fuente)
    except expr.ErrorExpresion as e:
        assert isinstance(e.pos, int), (fuente, type(e.pos))
        assert 0 <= e.pos <= len(fuente) + 1, (fuente, e.pos)
        assert isinstance(e.mensaje, str) and len(e.mensaje) >= 5, (fuente, e.mensaje)
        assert len(str(e)) >= 5
    except Exception as e:
        raise AssertionError('excepcion CRUDA %r (%s) con %r' % (e, type(e).__name__, fuente))
    else:
        raise AssertionError('no fallo con la entrada invalida %r' % fuente)
try:
    expr.evaluar('1 + * 2')
except expr.ErrorExpresion as e:
    assert e.pos == 4, 'la posicion del error deberia ser 4 y fue %r' % (e.pos,)
en = expr.Entorno()
en.definir_funcion('bucle', ['n'], 'bucle(n)')
try:
    expr.evaluar('bucle(1)', en)
except expr.ErrorExpresion:
    pass
except Exception as e:
    raise AssertionError('la recursion infinita salio como %s, no como ErrorExpresion' % type(e).__name__)
else:
    raise AssertionError('la recursion infinita no dio error')
en2 = expr.Entorno()
en2.definir_funcion('uno', ['a'], 'a')
try:
    expr.evaluar('uno(1, 2)', en2)
except expr.ErrorExpresion:
    pass
else:
    raise AssertionError('no comprueba la aridad de las funciones de usuario')
assert abs(expr.evaluar('1 + 1') - 2) < 1e-9, 'la libreria quedo rota tras los errores'
